<section class="panel table-wrap<?= !empty($admin_screen) ? ' card card-body extension-panel' : '' ?>"><?php if ($orders === []): ?><p>해당하는 주문이 없습니다.</p><?php else: ?><table class="table"><thead><tr><th>주문일 / 주문번호</th><th>상품</th><th>상태</th><th>결제사</th><th class="num">결제 / 환불</th><th></th></tr></thead><tbody><?php foreach ($orders as $row): ?><tr><td data-label="주문일 / 주문번호"><?= $this->e($time($row['created_at'])) ?><br><span class="order-id"><?= $this->e($row['id']) ?></span></td><td data-label="상품"><?= $this->e($row['order_name']) ?><?php if ($row['environment'] === 'test'): ?><br><span class="badge test-tag badge-soft">테스트</span><?php endif ?></td><td data-label="상태"><span class="badge badge-soft"><?= $this->e($status_labels[$row['status']] ?? $row['status']) ?></span><?php if ((int) $row['open_claims'] > 0): ?><p class="highlight">미처리 신청 <?= (int) $row['open_claims'] ?>건</p><?php endif ?><?php if ($row['needs_review']): ?><p class="highlight">확인 필요</p><?php endif ?></td><td data-label="결제사"><?= $this->e($providers[$row['provider']] ?? $row['provider']) ?></td><td data-label="결제 / 환불" class="num"><?= number_format((int) $row['total']) ?>원<br><small>환불 <?= number_format((int) $row['refunded']) ?>원</small></td><td data-label="관리"><a class="link" href="<?= $this->e($url) ?>/<?= $page === 'admin' ? 'manage-order' : 'order' ?>?id=<?= $this->e($row['id']) ?>">상세 →</a></td></tr><?php endforeach ?></tbody></table><?php endif ?></section>
<nav class="pagination"><?php if ($page_number > 1): ?><a class="link" href="<?= $this->e($url . ($page === 'admin' ? '' : '/' . $page)) ?>?<?= $this->e(http_build_query(array_replace($input, ['p' => $page_number - 1]))) ?>">← 이전</a><?php endif ?><?php if (count($orders) === 30): ?><a class="link" href="<?= $this->e($url . ($page === 'admin' ? '' : '/' . $page)) ?>?<?= $this->e(http_build_query(array_replace($input, ['p' => $page_number + 1]))) ?>">다음 →</a><?php endif ?></nav>
